svg.script:
(function () {
  var SVGNS = 'http://www.w3.org/2000/svg';
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var drawHearth;
  // ---- Fireplace: two logs go on the fire, then time fast-forwards and they burn down ----
  var fp = document.getElementById('fp');
  if (fp) {
    var fq = function (id) { return document.getElementById(id); };
    var fpTime = fq('fpTime'), fpPlus = fq('fpPlus'), fpFF = fq('fpFF'), fpCap = fq('fpCap'), fpPill = fq('fpPill'),
        fpFlames = fq('fpFlames'), fpLight = fq('fpLight'), fpInner = fq('fpInner'),
        fpDrag = fq('fpDrag'), fpCursor = fq('fpCursor'), fpTop = fq('fpPileTop'),
        fpSparks = fq('fpSparks').getElementsByTagName('circle'),
        fpLogs = [0, 1, 2].map(function (i) { return [fq('fpLog' + i), fq('fpChar' + i), fq('fpCrack' + i)]; });
    // where logs rest on the grate, the top of the woodpile, and where the cursor waits
    var SLOT = [[150, 205, 0], [139, 196, -8], [161, 188, 7]], PILE = [315, 165], REST = [374, 128];
    // 10 s loop at 15:00: drag a log on (+15:00), drag another (+15:00),
    // then fast-forward through two 15-minute marks back to 15:00
    var DRAGS = [[600, 1400, 1], [2050, 2850, 2]], MARKS = [6400, 8800], FF = [3700, 8800];
    var BURSTS = [[1400, 1], [2850, 2], [6400, 0], [8800, 0]];
    var LEVEL = [[0, .55], [1400, .55], [1900, .78], [2850, .78], [3350, 1], [3700, 1], [6300, .9], [6800, .72], [8700, .66], [9200, .55], [10000, .55]];
    var clamp01 = function (x) { return Math.max(0, Math.min(1, x)); };
    var ease = function (x) { x = clamp01(x); return x * x * (3 - 2 * x); };
    var mix = function (a, b, k) { return a + (b - a) * k; };
    var span = function (f, a, b) { return clamp01((f - a) / (b - a)); };
    var between = function (a, b, k) { return [mix(SLOT[a][0], SLOT[b][0], k), mix(SLOT[a][1], SLOT[b][1], k), mix(SLOT[a][2], SLOT[b][2], k)]; };
    var fireLevel = function (f) {
      for (var i = 1; i < LEVEL.length; i++) {
        if (f <= LEVEL[i][0]) return mix(LEVEL[i - 1][1], LEVEL[i][1], ease((f - LEVEL[i - 1][0]) / (LEVEL[i][0] - LEVEL[i - 1][0])));
      }
      return LEVEL[0][1];
    };
    var secondsLeft = function (f) {
      if (f < 1400) return 900 - f / 1000;
      if (f < 2850) return 898.6 - (f - 1400) / 1000 + 900 * ease((f - 1400) / 400);
      if (f < 3700) return 1797.15 - (f - 2850) / 1000 + 900 * ease((f - 2850) / 400);
      if (f < 6400) return mix(2696.3, 1800, ease(span(f, 3700, 6400)));
      if (f < 8800) return mix(1800, 900, ease(span(f, 6400, 8800)));
      return 900;
    };
    // each log on the grate: [position, how burnt, opacity, squash]. The oldest log chars as it
    // burns, collapses at the mark, and the logs above it drop into its place.
    var logState = function (i, f) {
      if (i === 0) {
        if (f < 6400) return [SLOT[0], f < 3700 ? .3 : mix(.3, 1, span(f, 3700, 6400)), 1, 1 - .3 * ease(span(f, 5400, 6400))];
        if (f < 6800) return [SLOT[0], 1, 1 - span(f, 6400, 6800), .7 * (1 - .7 * span(f, 6400, 6800))];
        return [SLOT[0], 1, 0, 1];
      }
      if (i === 1) {
        if (f < 1400) return [SLOT[1], 0, 0, 1];
        if (f < 6400) return [SLOT[1], .12 + .1 * span(f, 1400, 6400), 1, 1];
        if (f < 8800) return [between(1, 0, ease(span(f, 6400, 6900))), mix(.3, 1, span(f, 6400, 8800)), 1, 1 - .3 * ease(span(f, 7900, 8800))];
        if (f < 9200) return [SLOT[0], 1, 1 - span(f, 8800, 9200), .7 * (1 - .7 * span(f, 8800, 9200))];
        return [SLOT[0], 1, 0, 1];
      }
      if (f < 2850) return [SLOT[2], 0, 0, 1];
      if (f < 6400) return [SLOT[2], .12, 1, 1];
      if (f < 8800) return [between(2, 1, ease(span(f, 6400, 6900))), .14, 1, 1];
      return [between(1, 0, ease(span(f, 8800, 9300))), mix(.14, .3, span(f, 8800, 9300)), 1, 1];
    };
    var place = function (el, p, sx, sy, o) {
      el.setAttribute('transform', 'translate(' + p[0].toFixed(1) + ' ' + p[1].toFixed(1) + ') rotate(' + p[2].toFixed(1) + ') scale(' + sx.toFixed(3) + ' ' + sy.toFixed(3) + ')');
      el.setAttribute('opacity', o.toFixed(2));
    };
    var lastCap = '';
    var drawHearth = function (t) {
      var f = t % 10000, lv = fireLevel(f), flick = 0.9 + 0.1 * Math.sin(t * 0.013) * Math.sin(t * 0.0071 + 1);
      var s = Math.ceil(secondsLeft(f)), mm = Math.floor(s / 60), ss = s % 60;
      fpTime.textContent = (mm < 10 ? '0' : '') + mm + ':' + (ss < 10 ? '0' : '') + ss;

      fpFlames.setAttribute('transform', 'translate(150 210) scale(' + (0.6 + 1.1 * lv).toFixed(3) + ')');
      fpLight.setAttribute('opacity', (0.35 + 0.65 * lv * flick).toFixed(2));
      fpInner.setAttribute('opacity', (0.4 + 0.6 * lv * flick).toFixed(2));

      for (var i = 0; i < 3; i++) {
        var st = logState(i, f), burnt = st[1], log = fpLogs[i];
        place(log[0], st[0], 1 - (1 - st[3]) * 0.25, st[3], st[2]);
        log[1].setAttribute('opacity', (burnt * 0.85).toFixed(2));
        log[2].setAttribute('opacity', (ease((burnt - 0.35) / 0.55) * (0.55 + 0.45 * flick) * Math.min(1, lv * 1.3)).toFixed(2));
      }

      // the cursor glides to the woodpile and carries a log along an arc onto the grate
      var d = null, cur = REST, curO = 0, held = false;
      for (var j = 0; j < DRAGS.length; j++) if (f >= DRAGS[j][0] - 400 && f < DRAGS[j][1] + 250) d = DRAGS[j];
      if (d) {
        var pick = d[0], land = d[1], to = SLOT[d[2]];
        if (f < pick) {
          var k0 = ease(span(f, pick - 400, pick));
          cur = [mix(REST[0], PILE[0], k0), mix(REST[1], PILE[1], k0)];
          curO = span(f, pick - 400, pick - 250);
        } else if (f < land) {
          var k = ease(span(f, pick + 60, land)), u = 1 - k, k1 = ease(span(f, pick, pick + 320));
          var mx = (PILE[0] + to[0]) / 2, my = Math.min(PILE[1], to[1]) - 70;
          var lx = u * u * PILE[0] + 2 * u * k * mx + k * k * to[0], ly = u * u * PILE[1] + 2 * u * k * my + k * k * to[1];
          place(fpDrag, [lx, ly, mix(75, to[2] - 14, k1) + 14 * k], mix(0.3, 1.08, k1) - 0.08 * k, mix(0.9, 1.08, k1) - 0.08 * k, 1);
          held = true;
          cur = [lx + 2, ly + 1];
          curO = 1;
        } else {
          var k2 = ease(span(f, land, land + 250));
          cur = [mix(to[0] + 2, REST[0], k2), mix(to[1] + 1, REST[1], k2)];
          curO = 1 - span(f, land + 60, land + 250);
        }
      }
      if (!held) fpDrag.setAttribute('opacity', 0);
      fpCursor.setAttribute('transform', 'translate(' + cur[0].toFixed(1) + ' ' + cur[1].toFixed(1) + ')');
      fpCursor.setAttribute('opacity', curO.toFixed(2));

      // the woodpile never runs out: its top log is gone while carried, then rolls back in
      var top = 1;
      DRAGS.forEach(function (dd) { if (f >= dd[0] && f < dd[1] + 600) top = f < dd[1] + 380 ? 0 : ease(span(f, dd[1] + 380, dd[1] + 600)); });
      fpTop.setAttribute('opacity', top.toFixed(2));
      fpTop.setAttribute('transform', 'translate(315 165) scale(' + (0.6 + 0.4 * top).toFixed(3) + ') translate(-315 -165)');

      // sparks when a log lands and when one collapses at a mark
      var burst = null;
      BURSTS.forEach(function (b) { if (f >= b[0] && f < b[0] + 900) burst = b; });
      for (var n = 0; n < fpSparks.length; n++) {
        var sp = fpSparks[n];
        if (!burst) { sp.setAttribute('opacity', 0); continue; }
        var dt = (f - burst[0]) / 1000, o = SLOT[burst[1]];
        var a = -1.5708 + ((n * 0.618) % 1 - 0.5) * 1.7, v = 24 + ((n * 0.377) % 1) * 36, life = 0.5 + ((n * 0.531) % 1) * 0.4;
        sp.setAttribute('cx', (o[0] + Math.cos(a) * v * dt + Math.sin(dt * 10 + n) * 1.5).toFixed(1));
        sp.setAttribute('cy', (o[1] - 5 + Math.sin(a) * v * dt).toFixed(1));
        sp.setAttribute('opacity', Math.max(0, 1 - dt / life).toFixed(2));
      }

      var plus = 0, rise = 0;
      [DRAGS[0][1], DRAGS[1][1]].forEach(function (te) { if (f >= te && f < te + 800) { var kp = (f - te) / 800; plus = 1 - kp * kp; rise = -9 * ease(kp); } });
      fpPlus.setAttribute('opacity', plus.toFixed(2));
      fpPlus.setAttribute('transform', 'translate(0 ' + rise.toFixed(1) + ')');

      var ff = f >= FF[0] && f < FF[1], pulse = 0;
      MARKS.forEach(function (m) { pulse = Math.max(pulse, 1 - Math.abs(f - m) / 350); });
      fpFF.setAttribute('opacity', ff ? 0.85 : 0);
      fpPill.setAttribute('stroke-opacity', (0.45 + 0.55 * pulse).toFixed(2));

      var cap = f < FF[0] ? 'DRAG A LOG ONTO THE FIRE · +15 MIN EACH' : ff ? 'FAST-FORWARD · A LOG BURNS DOWN EVERY 15 MIN' : 'KEEP FEEDING IT AND IT KEEPS BURNING';
      if (cap !== lastCap) { fpCap.textContent = cap; lastCap = cap; }
    };
  }

  if (!drawHearth) return;
  var start = performance.now(), last = 0;
  function frame(now) {
    if (now - last > 33) { last = now; drawHearth(Math.max(0, now - start)); }
    requestAnimationFrame(frame);
  }
  if (reduce) drawHearth(3690); else requestAnimationFrame(frame);
})();
